<?php
require_once __DIR__ . '/../includes/init.php';requireAdmin();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);
 if($action==='delete'){if($id===(int)currentUser()['id'])flash('error','You cannot delete your own account.');else{$s=$pdo->prepare('SELECT COUNT(*) FROM stock_movements WHERE created_by=?');$s->execute([$id]);if($s->fetchColumn())flash('error','This user is linked to stock movement history and cannot be deleted.');else{$d=$pdo->prepare('DELETE FROM users WHERE id=?');$d->execute([$id]);flash('success','User deleted.');}}redirect('admin/users.php');}
 if($action==='save'){$name=trim((string)($_POST['full_name']??''));$username=trim((string)($_POST['username']??''));$role=(string)($_POST['role']??'');$password=(string)($_POST['password']??'');if(!$name||!preg_match('/^[A-Za-z0-9_.-]{3,50}$/',$username)||!in_array($role,['admin','user'],true)||(!$id&&strlen($password)<8)||($password!==''&&strlen($password)<8))flash('error','Enter a name, valid username, role and password of at least 8 characters.');else{try{if($id){if($password!==''){$s=$pdo->prepare('UPDATE users SET full_name=?,username=?,role=?,password_hash=? WHERE id=?');$s->execute([$name,$username,$role,password_hash($password,PASSWORD_DEFAULT),$id]);}else{$s=$pdo->prepare('UPDATE users SET full_name=?,username=?,role=? WHERE id=?');$s->execute([$name,$username,$role,$id]);}if($id===(int)currentUser()['id']){$_SESSION['user']['full_name']=$name;$_SESSION['user']['username']=$username;$_SESSION['user']['role']=$role;}flash('success','User updated.');}else{$s=$pdo->prepare('INSERT INTO users(full_name,username,password_hash,role) VALUES(?,?,?,?)');$s->execute([$name,$username,password_hash($password,PASSWORD_DEFAULT),$role]);flash('success','User created.');}}catch(PDOException $e){flash('error',$e->getCode()==='23000'?'That username is already in use.':'Unable to save user.');}}redirect('admin/users.php');}
}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT id,full_name,username,role FROM users WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$users=$pdo->query('SELECT id,full_name,username,role,is_active,created_at,updated_at FROM users ORDER BY full_name')->fetchAll();$title='Users';$active='users';layoutStart($title,$active);
?><div class="page-heading"><div><div class="eyebrow">ACCESS CONTROL</div><h1>Users</h1><p>Manage accounts and access to the warehouse.</p></div></div><?php if($edit):?><section class="panel form-panel"><div class="panel-heading"><div><h2>Edit user</h2><p>Leave password blank to keep the current password.</p></div></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?= e(csrfToken()) ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= e($edit['id']) ?>"><label>Full name<input name="full_name" value="<?= e($edit['full_name']) ?>" required></label><label>Username<input name="username" value="<?= e($edit['username']) ?>" required></label><label>Role<select name="role"><option value="admin" <?= $edit['role']==='admin'?'selected':'' ?>>Admin</option><option value="user" <?= $edit['role']==='user'?'selected':'' ?>>User</option></select></label><label>New password<input type="password" name="password" minlength="8" autocomplete="new-password" placeholder="Leave blank to keep current"></label><div class="form-actions"><button class="button primary">Save changes</button><a class="button light" href="<?= e(url('admin/users.php')) ?>">Cancel</a></div></form></section><?php else:?><details class="panel collapsible"><summary><span><b>Add user</b><small>Create an admin or read-only account</small></span><span class="button primary compact">＋ Add user</span></summary><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?= e(csrfToken()) ?>"><input type="hidden" name="action" value="save"><label>Full name<input name="full_name" required></label><label>Username<input name="username" minlength="3" required></label><label>Role<select name="role"><option value="user">User</option><option value="admin">Admin</option></select></label><label>Password<input type="password" name="password" minlength="8" required></label><div class="form-actions"><button class="button primary">Create user</button></div></form></details><?php endif;?><section class="panel"><div class="panel-heading"><div><h2>Team accounts</h2><p><?= count($users) ?> user accounts</p></div></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Name</th><th>Username</th><th>Role</th><th>Created</th><th>Updated</th><th>Actions</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?= e($u['id']) ?></td><td><b><?= e($u['full_name']) ?></b><?php if($u['id']==currentUser()['id']):?><small class="subtext">You</small><?php endif;?></td><td><?= e($u['username']) ?></td><td><span class="badge <?= $u['role']==='admin'?'role-admin':'role-user' ?>"><?= e(ucfirst($u['role'])) ?></span></td><td><?= e(dateValue($u['created_at'])) ?></td><td><?= e(dateValue($u['updated_at'])) ?></td><td class="actions"><a class="text-link" href="<?= e(url('admin/users.php?edit='.$u['id'])) ?>">Edit / reset password</a><?php if($u['id']!=currentUser()['id']):?><form method="post" data-confirm="Delete this user account?"><input type="hidden" name="csrf" value="<?= e(csrfToken()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= e($u['id']) ?>"><button class="link-danger">Delete</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section><?php layoutEnd();?>
